#!/usr/bin/env bash
# Description: Generate the complete append-only Audit Logging foundation.

set -Eeuo pipefail

PROJECT_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
PATCH_FILE="$(mktemp /tmp/company-ai-audit-logging.XXXXXX.patch)"

cleanup() {
    rm -f "${PATCH_FILE}"
}

trap cleanup EXIT

printf '%s\n' "======================================"
printf '%s\n' " Company AI - Add Audit Logging"
printf '%s\n' "======================================"
printf '\n'

base64 --decode <<'AUDIT_LOGGING_PATCH' | gzip -d > "${PATCH_FILE}"

AUDIT_LOGGING_PATCH

if git -C "${PROJECT_ROOT}" apply --reverse --check "${PATCH_FILE}" \
    >/dev/null 2>&1
then
    printf '%s\n' "Audit Logging implementation is already present."
elif git -C "${PROJECT_ROOT}" apply --check "${PATCH_FILE}"; then
    git -C "${PROJECT_ROOT}" apply "${PATCH_FILE}"
    printf '%s\n' "Audit Logging implementation generated."
else
    printf '%s\n' \
        "ERROR: Audit Logging patch conflicts with the current source tree." \
        "No implementation files were changed." >&2
    exit 1
fi

printf '%s\n' "Migration 0005 was created but was not applied."

if [[ -x "${PROJECT_ROOT}/scripts/maintenance/update-project-status.sh" ]]; then
    "${PROJECT_ROOT}/scripts/maintenance/update-project-status.sh"
fi

printf '\n%s\n' "Audit Logging setup completed successfully."
